#!/usr/bin/env node
// The one that is actually used. See README.md.
import { readdir } from 'node:fs/promises';

const dir = process.argv[2] || '.';
const files = await readdir(dir);
for (const f of files) {
  if (!/\.(png|jpg)$/i.test(f)) continue;
  console.log('would resize', f);
}

// First attempt, kept 'just in case' in early 2025. Superseded by resize.mjs.
const fs = require('fs');
fs.readdir('.', (e, files) => console.log(files));

